	@Test
	@Timeout(value = 90, unit = TimeUnit.SECONDS)
	void anotherOwnersLiveForecastCannotInflateTheCurrentWritersEmergencyResize(@TempDir Path dataDir)
			throws Exception {
		InspectableLmdbStore store = new InspectableLmdbStore(dataDir.toFile(), smallMapConfig());
		SailClosable unrelatedForecast = null;
		try {
			store.init();
			LmdbSailStore backing = store.getBackingStore();
			backing.enableMultiThreading = false;
			ValueStore valueStore = store.capturedValueStore();
			TripleStore tripleStore = store.capturedTripleStore();
			long initialValueMapBytes = valueStore.mapSizeBytes();
			long initialTripleMapBytes = tripleStore.mapSizeBytes();
			long initialOccupiedBytes = valueStore.occupiedBytes();
			List<Statement> unrelatedPlan = dictionaryBatch("unrelated-owner", 0, VALUE_COUNT, LITERAL_LENGTH);
			long unrelatedEstimate = estimate(valueStore, unrelatedPlan);
			long unrelatedForecastTarget = new MapGrowthPolicy(LmdbStoreConfig.MAP_GROWTH_THRESHOLD)
					.grownMapSize(initialValueMapBytes, 4096L,
							LmdbUtil.saturatedAdd(initialOccupiedBytes, unrelatedEstimate));

			try (LmdbStoreConnection writer = (LmdbStoreConnection) store.getConnection();
					LmdbStoreConnection unrelated = (LmdbStoreConnection) store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				SailSource writerSource = backing.getExplicitSailSource(writer);
				Statement writerPrefix = dictionaryBatch("current-writer", 0, 1, 32).getFirst();
				try (SailSink sink = writerSource.sink(IsolationLevels.NONE)) {
					sink.approve(writerPrefix.getSubject(), writerPrefix.getPredicate(), writerPrefix.getObject(),
							null);

					unrelated.begin(IsolationLevels.SNAPSHOT);
					SailSource unrelatedSource = backing.getExplicitSailSource(unrelated);
					unrelatedForecast = unrelatedSource.beginWritePreflight(writePreflight(unrelatedPlan), unrelated);
					List<Statement> writerSuffix = dictionaryBatch("current-writer", 1, VALUE_COUNT, LITERAL_LENGTH);
					MapGrowthMetrics.Snapshot beforeEmergency = backing.growthMetricsSnapshot();
					long firstEmergencyMapBytes = -1L;
					for (Statement statement : writerSuffix) {
						sink.approve(statement.getSubject(), statement.getPredicate(), statement.getObject(), null);
						MapGrowthMetrics.Snapshot current = backing.growthMetricsSnapshot();
						if (firstEmergencyMapBytes < 0L
								&& current.emergencyAttempts() > beforeEmergency.emergencyAttempts()) {
							firstEmergencyMapBytes = valueStore.mapSizeBytes();
						}
					}
					sink.flush();
					assertTrue(firstEmergencyMapBytes > initialValueMapBytes,
							"the current writer must exercise a real native hard-capacity resize");
					assertTrue(firstEmergencyMapBytes < unrelatedForecastTarget,
							"emergency sizing must select the writer's exact owner, not an unrelated live forecast; "
									+ "unrelatedTarget=" + unrelatedForecastTarget + ", firstEmergencyMapBytes="
									+ firstEmergencyMapBytes + ", metrics=" + beforeEmergency + "->"
									+ backing.growthMetricsSnapshot());
				}
				writer.commit();
				unrelated.rollback();
			}

			List<Statement> expected = new ArrayList<>();
			expected.add(dictionaryBatch("current-writer", 0, 1, 32).getFirst());
			expected.addAll(dictionaryBatch("current-writer", 1, VALUE_COUNT, LITERAL_LENGTH));
			assertCompletePublication(store, expected);
			assertTrue(valueStore.retainsGrowthReserve(),
					"the current writer's map must retain reserve for its committed native allocations");
			assertEquals(initialTripleMapBytes, tripleStore.mapSizeBytes(),
					"unrelated ValueStore demand must not resize the TripleStore map");
		} finally {
			if (unrelatedForecast != null) {
				unrelatedForecast.close();
			}
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 90, unit = TimeUnit.SECONDS)
	void explicitAndInferredBranchesRetainTheirCombinedValueStoreEstimate(@TempDir Path dataDir) throws Exception {
		InspectableLmdbStore store = new InspectableLmdbStore(dataDir.toFile(), smallMapConfig());
		try {
			store.init();
			LmdbSailStore backing = store.getBackingStore();
			backing.enableMultiThreading = false;
			List<Statement> explicit = dictionaryBatch("grouped-explicit", 0, VALUE_COUNT / 2, LITERAL_LENGTH);
			List<Statement> inferred = dictionaryBatch("grouped-inferred", VALUE_COUNT / 2, VALUE_COUNT / 2,
					LITERAL_LENGTH);
			List<Statement> planned = new ArrayList<>(explicit);
			planned.addAll(inferred);
			ValueStore valueStore = store.capturedValueStore();
			TripleStore tripleStore = store.capturedTripleStore();
			long initialValueMapBytes = valueStore.mapSizeBytes();
			long initialTripleMapBytes = tripleStore.mapSizeBytes();
			long initialOccupiedBytes = valueStore.occupiedBytes();
			long projectedValueBytes = estimate(valueStore, planned);
			assertInitialValueDemandRequiresGrowth(initialValueMapBytes, initialOccupiedBytes, projectedValueBytes);
			MapGrowthMetrics.Snapshot growthBefore = backing.growthMetricsSnapshot();

			try (LmdbStoreConnection connection = (LmdbStoreConnection) store.getConnection()) {
				connection.begin(IsolationLevels.SNAPSHOT);
				for (Statement statement : explicit) {
					connection.addStatement(statement.getSubject(), statement.getPredicate(), statement.getObject(),
							statement.getContext());
				}
				for (Statement statement : inferred) {
					assertTrue(connection.addInferredStatement(statement.getSubject(), statement.getPredicate(),
							statement.getObject(), statement.getContext()),
							"the inferred half of the grouped write must be retained");
				}
				connection.prepare();
				assertEquals(initialValueMapBytes, valueStore.mapSizeBytes(),
						"preparing explicit and inferred branches must not resize before publication");
				connection.commit();
			}

			assertCompletePublication(store, planned);
			MapGrowthMetrics.Snapshot growthAfter = backing.growthMetricsSnapshot();
			assertTrue(growthAfter.emergencyAttempts() > growthBefore.emergencyAttempts(),
					"the grouped explicit/inferred write must reach native emergency sizing; before=" + growthBefore
							+ ", after=" + growthAfter);
			assertProjectedValueDemand(valueStore, initialValueMapBytes, initialOccupiedBytes, projectedValueBytes,
					"the shared ValueStore must retain demand from both branches under their publishing owner; "
							+ "emergencyAttempts=" + growthBefore.emergencyAttempts() + "->"
							+ growthAfter.emergencyAttempts());
			assertEquals(initialTripleMapBytes, tripleStore.mapSizeBytes(),
					"the combined dictionary forecast must leave the uninvolved TripleStore map unchanged");
		} finally {
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 60, unit = TimeUnit.SECONDS)
	void directPreflightCoversDeclaredSuffixBeforeTheFirstNativeValueIsPublished(@TempDir Path dataDir)
			throws Exception {
		InspectableLmdbStore store = new InspectableLmdbStore(dataDir.toFile(), smallMapConfig());
		try {
			store.init();
			LmdbSailStore backing = store.getBackingStore();
			backing.enableMultiThreading = false;
			ValueStore valueStore = store.capturedValueStore();
			TripleStore tripleStore = store.capturedTripleStore();
			List<Statement> planned = dictionaryBatch("direct-suffix", 1, VALUE_COUNT - 1, LITERAL_LENGTH);
			planned.add(0, dictionaryStatement("direct-suffix", 0, 12 * LITERAL_LENGTH));
			long initialValueMapBytes = valueStore.mapSizeBytes();
			long initialTripleMapBytes = tripleStore.mapSizeBytes();
			long initialOccupiedBytes = valueStore.occupiedBytes();
			long projectedValueBytes = estimate(valueStore, planned);
			assertInitialValueDemandRequiresGrowth(initialValueMapBytes, initialOccupiedBytes, projectedValueBytes);
			MapGrowthMetrics.Snapshot before = backing.growthMetricsSnapshot();
			Object publishingOwner = new Object();
			SailSource source = backing.getExplicitSailSource(publishingOwner);
			SailSource.WritePreflight completeEstimate = writePreflight(planned);

			try (SailClosable owner = backing.enterWriterOwner(publishingOwner);
					SailClosable forecast = source.beginWritePreflight(completeEstimate, publishingOwner);
					SailSink sink = source.sink(IsolationLevels.NONE)) {
				sink.approve(planned.get(0).getSubject(), planned.get(0).getPredicate(), planned.get(0).getObject(),
						null);
				assertTrue(backing.growthMetricsSnapshot().emergencyAttempts() > before.emergencyAttempts(),
						"the first dictionary allocation must exercise native emergency sizing while its suffix is pending");
				assertProjectedValueDemand(valueStore, initialValueMapBytes, initialOccupiedBytes, projectedValueBytes,
						"a live exact-owner preflight must size the first native continuation for its complete declared suffix");

				for (int index = 1; index < planned.size(); index++) {
					Statement statement = planned.get(index);
					sink.approve(statement.getSubject(), statement.getPredicate(), statement.getObject(), null);
				}
				sink.flush();
			}

			assertCompletePublication(store, planned);
			long completedGenerationMapBytes = valueStore.mapSizeBytes();
			long completedGenerationResizes = backing.growthMetricsSnapshot().valueStoreResizes();
			try (SailSink nextGeneration = source.sink(IsolationLevels.NONE)) {
				Statement statement = dictionaryBatch("completed-generation", 0, 1, 32).getFirst();
				nextGeneration.approve(statement.getSubject(), statement.getPredicate(), statement.getObject(), null);
				nextGeneration.flush();
			}
			assertEquals(completedGenerationMapBytes, valueStore.mapSizeBytes(),
					"a completed forecast must not inflate a later generation for the same owner");
			assertEquals(completedGenerationResizes, backing.growthMetricsSnapshot().valueStoreResizes(),
					"the later same-owner generation must not reopen the completed forecast");
			assertCompletePublication(store, plannedWithNextGeneration(planned));
			assertEquals(initialTripleMapBytes, tripleStore.mapSizeBytes(),
					"a ValueStore-only emergency forecast must not resize the TripleStore map");
		} finally {
			store.shutDown();
		}
	}

